function App() {
  const [count, setCount] = useState(0)
  const [items, setItems] = useState([
    { id: 'a', text: 'Buy milk' },
    { id: 'b', text: 'Call Sam' },
  ])
  return (
    <div>
      <button onClick={() => setCount(count + 1)}>Plus A</button>
      <button onClick={() => setCount(count + 1)}>Plus B</button>
      <p>Count: {count}</p>
      <ul>
        {items.map((item, index) => (
          <Row key={index} item={item} />
        ))}
      </ul>
    </div>
  )
}

